CI/CD integration:
#!/bin/bash
# health-check.sh — verify GraphQL API is responsive
RESPONSE=$(gql-explorer query "$GRAPHQL_ENDPOINT" \
-H "Authorization:Bearer $API_TOKEN" \
-q '{ __typename }' 2>/dev/null)
