format?: 'png' | 'jpeg' | 'webp';
fullPage?: boolean;
}
app.post('/api/screenshot', async (req: Request<{}, {}, ScreenshotBody>, res: Response) => {
const { url, format = 'png', fullPage = true } = req.body;
if (!url) {
return res.status(400).json({ error: 'url is required' });
}
try {
