3.8 Testing Async Code
Q1: How do you test async functions in Flutter?
Answer:
void main() {
test('async function returns correct value', () async {
final service = UserService();
final result = await service.fetchUser(1);
expect(result.name, 'John');
});
test('async function throws on error', () async {
final service = UserService();
expect(
() async => await service.fetchUser(-1),
throwsA(isA<NotFoundException>()),
);
});
// Using Completer for fine-grained control
test('handles concurrent requests', () async {
final completer1 = Completer<User>();
final completer2 = Completer<User>();
final mockRepo = MockUserRepository();
var callCount = 0;
when(() => mockRepo.getUser(any())).thenAnswer((_) {
callCount++;
return callCount == 1 ? completer1.future : completer2.future;
});
final service = UserService(mockRepo);
// Start two concurrent requests
final future1 = service.getUser(1);
final future2 = service.getUser(2);
// Complete in reverse order
completer2.complete(User(id: 2, name: 'Jane'));
completer1.complete(User(id: 1, name: 'John'));
final user1 = await future1;
final user2 = await future2;
expect(user1.name, 'John');
expect(user2.name, 'Jane');
});
}
Q2: How do you test Streams in Flutter?
Answer:
void main() {
test('stream emits correct sequence', () {
final controller = StreamController<int>();
final stream = controller.stream;
// expectLater with stream matchers
expectLater(
stream,
emitsInOrder([1, 2, 3, emitsDone]),
);
controller.add(1);
controller.add(2);
controller.add(3);
controller.close();
});
test('stream emits error', () {
final controller = StreamController<int>();
expectLater(
controller.stream,
emitsInOrder([
1,
emitsError(isA<Exception>()),
2,
]),
);
controller.add(1);
controller.addError(Exception('oops'));
controller.add(2);
controller.close();
});
test('stream never emits negative', () {
final controller = StreamController<int>();
expectLater(controller.stream, neverEmits(isNegative));
controller.add(1);
controller.add(2);
controller.add(3);
controller.close();
});
// Testing StreamTransformers
test('debounced search stream', () async {
final searchBloc = SearchBloc();
expectLater(
searchBloc.results,
emitsInOrder([
[], // Initial empty
['Flutter', 'Dart'], // Search results
]),
);
searchBloc.search('flu');
await Future.delayed(const Duration(milliseconds: 500));
});
// Testing BehaviorSubject / ValueStream
test('BehaviorSubject replays last value', () async {
final subject = BehaviorSubject<int>.seeded(0);
subject.add(1);
subject.add(2);
// New listener receives the last value (2), then 3
expectLater(subject.stream, emitsInOrder([2, 3]));
subject.add(3);
await subject.close();
});
}
Q3: How do you test code with delays and timeouts?
Answer:
import 'package:fake_async/fake_async.dart';
void main() {
// Using fakeAsync for code with delays
test('retry logic retries 3 times with delay', () {
fakeAsync((async) {
int attempts = 0;
final service = RetryService(
maxRetries: 3,
delay: const Duration(seconds: 2),
action: () {
attempts++;
if (attempts < 3) throw Exception('Fail');
return 'Success';
},
);
String? result;
service.execute().then((r) => result = r);
// First attempt fails immediately
async.elapse(Duration.zero);
expect(attempts, 1);
expect(result, isNull);
// Wait for first retry delay
async.elapse(const Duration(seconds: 2));
expect(attempts, 2);
expect(result, isNull);
// Wait for second retry delay
async.elapse(const Duration(seconds: 2));
expect(attempts, 3);
expect(result, 'Success');
});
});
// Set custom timeout for slow tests
test('slow operation completes within timeout', () async {
final result = await slowOperation();
expect(result, isNotNull);
}, timeout: const Timeout(Duration(seconds: 30)));
// Testing with real async (when fakeAsync is not suitable)
test('websocket receives messages', () async {
final ws = WebSocketService();
await ws.connect('ws://localhost:8080');
final messages = <String>[];
final subscription = ws.messages.listen(messages.add);
ws.send('ping');
// Wait a bit for the response
await Future.delayed(const Duration(milliseconds: 100));
expect(messages, contains('pong'));
await subscription.cancel();
await ws.disconnect();
});
}
Q4: How do you test code that uses Timer
, Future.delayed
, or scheduleMicrotask
?
Answer:
import 'package:fake_async/fake_async.dart';
class TokenRefresher {
Timer? _timer;
int refreshCount = 0;
void startAutoRefresh(Duration interval) {
_timer = Timer.periodic(interval, (_) {
refreshCount++;
});
}
void stop() {
_timer?.cancel();
}
}
void main() {
test('auto-refresh fires at correct intervals', () {
fakeAsync((async) {
final refresher = TokenRefresher();
refresher.startAutoRefresh(const Duration(minutes: 30));
expect(refresher.refreshCount, 0);
async.elapse(const Duration(minutes: 30));
expect(refresher.refreshCount, 1);
async.elapse(const Duration(minutes: 60));
expect(refresher.refreshCount, 3);
refresher.stop();
async.elapse(const Duration(minutes: 30));
expect(refresher.refreshCount, 3); // No more refreshes after stop
});
});
// Testing microtasks
test('microtask execution order', () {
fakeAsync((async) {
final order = <String>[];
Future.microtask(() => order.add('microtask'));
Future.delayed(Duration.zero, () => order.add('delayed'));
scheduleMicrotask(() => order.add('scheduled'));
// Flush microtasks
async.flushMicrotasks();
expect(order, ['microtask', 'scheduled']);
// Flush timers
async.flushTimers();
expect(order, ['microtask', 'scheduled', 'delayed']);
});
});
// Testing Zone-specific behavior
test('error handling in zones', () {
fakeAsync((async) {
final errors = <Object>[];
runZonedGuarded(() {
Future.delayed(const Duration(seconds: 1), () {
throw Exception('Delayed error');
});
}, (error, stack) {
errors.add(error);
});
async.elapse(const Duration(seconds: 2));
expect(errors, hasLength(1));
expect(errors.first, isA<Exception>());
});
});
}
Q5: How do you test code that uses Isolate.run
or compute
?
Answer:
// The function under test
Future<List<User>> parseUsersInBackground(String json) {
return Isolate.run(() => _parseUsers(json));
}
List<User> _parseUsers(String json) {
final list = jsonDecode(json) as List;
return list.map((e) => User.fromJson(e)).toList();
}
void main() {
// Option 1: Test the parsing function directly (skip isolate in tests)
test('parseUsers correctly parses JSON', () {
final json = jsonEncode([
{'id': 1, 'name': 'John'},
{'id': 2, 'name': 'Jane'},
]);
final users = _parseUsers(json);
expect(users, hasLength(2));
expect(users.first.name, 'John');
});
// Option 2: Test with the actual isolate (slower but more realistic)
test('parseUsersInBackground works across isolates', () async {
final json = jsonEncode([
{'id': 1, 'name': 'John'},
{'id': 2, 'name': 'Jane'},
]);
final users = await parseUsersInBackground(json);
expect(users, hasLength(2));
});
// Option 3: Abstract the computation strategy for testability
test('with injectable compute strategy', () async {
final service = DataService(
computeStrategy: (fn, arg) => Future.value(fn(arg)), // Synchronous in tests
);
final users = await service.loadUsers(jsonString);
expect(users, hasLength(2));
});
}
Best practice: Extract the pure function being run in the isolate and test it directly. Only test the isolate integration in integration tests.
Q6: How do you handle flaky async tests?
Answer:
// 1. Never depend on real timing -- use fakeAsync
// BAD:
test('bad: depends on real timing', () async {
startOperation();
await Future.delayed(const Duration(seconds: 2)); // Flaky!
expect(isComplete, isTrue);
});
// GOOD:
test('good: uses fakeAsync', () {
fakeAsync((async) {
startOperation();
async.elapse(const Duration(seconds: 2));
expect(isComplete, isTrue);
});
});
// 2. Use Completers for explicit synchronization
test('explicit sync with Completer', () async {
final dataLoaded = Completer<void>();
final service = UserService(
onLoaded: () => dataLoaded.complete(),
);
service.loadData();
await dataLoaded.future; // Waits until explicitly completed
expect(service.users, isNotEmpty);
});
// 3. Use expectLater for streams (it waits automatically)
test('stream test', () async {
await expectLater(
myStream,
emitsInOrder([1, 2, 3]),
); // Waits for events
});
// 4. Retry flaky tests in CI (last resort)
@Retry(3)
test('network-dependent test', () async {
// ...
});
Key principles:
- Never use
Future.delayed
to "wait for something" in tests - Use
fakeAsync
to control time deterministically - Use
Completer
for explicit synchronization points - Use stream matchers (
emits
,emitsInOrder
) that wait automatically - If a test is flaky, fix the root cause instead of adding retries

Confession time: I’ve read about the performance benefits of scroll-timeline()
, but when I see an impressive JavaScript scrollytelling site like this one, it makes me question if the performance of old-school, main-thread scrollytelling is all that bad. The other shoe drops when the creators of that site admit they “ran into real limits,” and “mobile technically works, but it loses parallax and chops compositions,” to the extent that they “chose to gate phones to protect the first impression.” Put another way: they couldn’t get it working on mobile, and it sounds like JavaScript performance may have been one of the culprits.
The creator of another of my favorite scrolling experiments — which also uses JavaScript and also works best on desktop — called out that his text vortex section “would look better if it were applied for each character rather than each word, but that’s incredibly difficult to pull off using this same technique without incurring an astronomical performance impact.”
Challenge accepted.
He may have inadvertently created a realistic benchmark test for smoothly animating hundreds of divs based on scrolling.
That’s our cue to see if we can make a lookalike effect using modern CSS features to smoothly spiral every character in a string of text as the user scrolls down. To give the original text vortex some CSS sibling rivalry, let’s give the new sibling-index()
function a whirl, although it is still waiting on Firefox support at the time of writing. Therefore, as a fallback for the CodePen below, you can also watch the video of the screen recording.
Confession #2: This uses some script
The only JavaScript is to split the text into a <div>
for each character, but the animation is pure CSS. I could have hardcoded all the markup instead, but that would make the HTML annoying to read and maintain. The following script makes it easy for you to experiment with the pen by tweaking the text content.
const el = document.querySelector(".vortex");
el.innerHTML = el.innerHTML.replaceAll(/\s/g, '⠀');
new SplitText(".title", { type: "chars", charsClass: "char" });
The SplitText
plugin referenced here is from the freely available GSAP library. The plugin is designed to be usable standalone outside GSAP, which is what’s happening here. It is nice and simple to use, and it even populates aria-label
so screen readers can see our text, regardless of the way we tokenize it. The one complication was that I wanted every space character to be in its own <div>
that I could position. The simplest way I could find was to replace the spaces with a special space character, which SplitText
will put into its own <div>
. If anyone knows a better way, I’d love to hear about it in the comments.
Now that we have each character living in its own <div>
, we can implement the CSS to handle the spiral animation.
.vortex {
position: fixed;
left: 50%;
height: 100vh;
animation-name: vortex;
animation-duration: 20s;
animation-fill-mode: forwards;
animation-timeline: scroll();
.char {
--radius: calc(10vh - (7vh/sibling-count() * sibling-index()));
--rotation: calc((360deg * 3/sibling-count()) * sibling-index());
position: absolute !important;
top: 50%;
left: 50%;
transform: rotate(var(--rotation))
translateY(calc(-2.9 * var(--radius)))
scale(calc(.4 - (.25/(sibling-count()) * sibling-index())));
animation-name: fade-in;
animation-ranger-start: calc(90%/var(sibling-count()) * var(--sibling-index()));
animation-fill-mode: forwards;
animation-timeline: scroll();
}
}
sibling-index()
and sibling-count()
Spiral and fade the elements using We use the sibling-count
and sibling-index
functions together to calculate a gradual decrease for several properties of the characters when the sibling-index
increases, using a formula like this:
propertyValue = startValue - ((reductionValue/totalCharacters) * characterIndex)
The first character starts near the maximum value. Each subsequent character subtracts a slightly larger fraction, so properties gradually dwindle to a chosen target value as the characters spiral inward. This technique is used to drive scale, rotation, and distance from the center.
If the goal had been to arrange the characters in a circle instead of a spiral, I would have used CSS trigonometric functions as demonstrated here. However, the spiral seemed simpler to calculate without trig. Evidently, the original JavaScript version that inspired my CSS text spiral didn’t use trig either. The scroll animation is relatively simple as it’s just scaling and rotating the entire parent element to give the illusion that the viewer is being sucked into the vortex.
The only animation applied to individual characters is fade-in
which is delayed increasingly for each character in the string, using another variation on the usage of the ratio of sibling-index()
to sibling-count()
. In this case, we increment animation-range-start
to stagger the delay before characters fade in as the user scrolls. It’s reminiscent of the infamous scroll-to-fade effect, and it makes me realize how often we reach for JavaScript just because it allows us to base styling on element indexes. Therefore, many JavaScript effects can likely be replaced with CSS once sibling-index()
goes Baseline. Please do let me know in the comments if you can think of other examples of JavaScript effects we could recreate in CSS using sibling-index()
.

tRPC in 2026: Full-Stack TypeScript Without the Boilerplate
If you've ever wasted an afternoon keeping your frontend types in sync with your backend API, tRPC is the library that will feel like a revelation.
In 2026, tRPC has become a staple of the modern TypeScript full-stack stack — sitting alongside Next.js, Prisma, and Supabase as a must-know tool for solo devs and small teams.
What Is tRPC?
tRPC stands for TypeScript Remote Procedure Call. The idea is simple:
Define your backend functions once. Call them from the frontend with full type safety — no code generation, no REST schemas, no GraphQL resolvers.
The result? A single source of truth for your entire app's API contract.
The Problem tRPC Solves
With traditional REST APIs:
- You define a route on the backend:
GET /api/users/:id
- You write a TypeScript interface on the frontend:
interface User { ... }
- You pray they stay in sync
They never do. Someone changes the backend, forgets to update the frontend type, and you get a runtime error that only surfaces in production.
With GraphQL, you solve the type problem but add huge complexity (resolvers, SDL, codegen).
tRPC gives you GraphQL-level type safety with zero overhead.
How tRPC Works (The Simple Version)
// server.ts
import { initTRPC } from '@trpc/server';
const t = initTRPC.create();
export const appRouter = t.router({
getUser: t.procedure
.input(z.object({ id: z.string() }))
.query(async ({ input }) => {
return await db.user.findUnique({ where: { id: input.id } });
}),
createPost: t.procedure
.input(z.object({ title: z.string(), content: z.string() }))
.mutation(async ({ input }) => {
return await db.post.create({ data: input });
}),
});
export type AppRouter = typeof appRouter;
// client.ts (Next.js page or component)
import { trpc } from '../utils/trpc';
function UserProfile({ userId }: { userId: string }) {
// Fully typed — TypeScript knows the shape of 'user'
const { data: user } = trpc.getUser.useQuery({ id: userId });
return <div>{user?.name}</div>; // No manual type annotation needed
}
Notice: no manual types exported, no code generation step. The AppRouter
type does all the work.
tRPC vs REST vs GraphQL in 2026
| REST | GraphQL | tRPC | |
|---|---|---|---|
| Type safety | ❌ Manual | ✅ (with codegen) | ✅ Automatic |
| Setup complexity | Low | High | Low |
| Runtime overhead | Low | Medium | Low |
| Learning curve | Easy | Hard | Easy |
| Best for | Public APIs | Large teams | Full-stack TS apps |
tRPC shines when you control both frontend and backend — which is most solo projects and startups.
The Modern tRPC Stack in 2026
Most developers combine tRPC with:
- Next.js (App Router or Pages Router)
- Prisma (ORM for database queries)
- Zod (runtime input validation — tRPC requires it)
- NextAuth / Clerk (authentication)
- Supabase or PlanetScale (database)
This stack is sometimes called T3 Stack (created by Theo Browne), and it has become one of the most popular starting points for production-grade Next.js apps.
Setting Up tRPC in a Next.js App (2026 Version)
1. Install dependencies
npm install @trpc/server @trpc/client @trpc/react-query @trpc/next @tanstack/react-query zod
2. Initialize tRPC
// src/server/trpc.ts
import { initTRPC, TRPCError } from '@trpc/server';
import { ZodError } from 'zod';
const t = initTRPC.context<Context>().create({
errorFormatter({ shape, error }) {
return {
...shape,
data: {
...shape.data,
zodError: error.cause instanceof ZodError ? error.cause.flatten() : null,
},
};
},
});
export const router = t.router;
export const publicProcedure = t.procedure;
export const protectedProcedure = t.procedure.use(({ ctx, next }) => {
if (!ctx.session?.user) throw new TRPCError({ code: 'UNAUTHORIZED' });
return next({ ctx: { ...ctx, session: ctx.session } });
});
3. Create your router
// src/server/routers/post.ts
import { z } from 'zod';
import { router, protectedProcedure, publicProcedure } from '../trpc';
export const postRouter = router({
getAll: publicProcedure.query(async ({ ctx }) => {
return ctx.db.post.findMany({ orderBy: { createdAt: 'desc' } });
}),
create: protectedProcedure
.input(z.object({ title: z.string().min(1).max(100), content: z.string() }))
.mutation(async ({ ctx, input }) => {
return ctx.db.post.create({
data: { ...input, authorId: ctx.session.user.id },
});
}),
delete: protectedProcedure
.input(z.object({ id: z.string() }))
.mutation(async ({ ctx, input }) => {
return ctx.db.post.delete({ where: { id: input.id } });
}),
});
Real-World Error Handling
One of tRPC's strengths is typed error handling:
import { TRPCClientError } from '@trpc/client';
try {
await trpc.post.create.mutate({ title: '', content: 'test' });
} catch (error) {
if (error instanceof TRPCClientError) {
// TypeScript knows the error shape
const zodError = error.data?.zodError;
console.log(zodError?.fieldErrors); // { title: ['String must contain at least 1 character'] }
}
}
No more any
error types or guessing the error shape at runtime.
When NOT to Use tRPC
tRPC is not for everything:
- Public APIs consumed by third parties → use REST or GraphQL
- Microservices with different tech stacks → REST/gRPC
- Mobile apps with native codebases → REST is easier to integrate
- Teams with backend specialists who don't know TypeScript → REST
If you're building a product solo or with a small TypeScript team? tRPC is almost always the right call.
5 tRPC Patterns Worth Knowing
1. Input validation with Zod
.input(z.object({
email: z.string().email(),
age: z.number().min(18).max(120),
}))
2. Middleware for auth
const authMiddleware = t.middleware(({ ctx, next }) => {
if (!ctx.user) throw new TRPCError({ code: 'UNAUTHORIZED' });
return next({ ctx: { user: ctx.user } });
});
3. Optimistic updates
const utils = trpc.useContext();
mutation.mutate(data, {
onSuccess: () => utils.post.getAll.invalidate(),
});
4. Subscriptions (WebSockets)
subscription: t.procedure.subscription(({ ctx }) => {
return observable<Message>((emit) => {
// WebSocket logic here
});
}),
5. Batching requests
